1	import { motion } from "framer-motion";
2	import { Children, type ReactNode } from "react";
3	
4	interface StaggerListProps {
5	  children: ReactNode;
6	  stagger?: number;
7	  duration?: number;
8	  direction?: "up" | "down" | "left" | "right" | "none";
9	  distance?: number;
10	  className?: string;
11	}
12	
13	const directionMap = {
14	  up: { y: 1, x: 0 },
15	  down: { y: -1, x: 0 },
16	  left: { x: 1, y: 0 },
17	  right: { x: -1, y: 0 },
18	  none: { x: 0, y: 0 },
19	};
20	
21	const StaggerList = ({
22	  children,
23	  stagger = 0.05,
24	  duration = 0.25,
25	  direction = "up",
26	  distance = 10,
27	  className,
28	}: StaggerListProps) => {
29	  const dir = directionMap[direction];
30	
31	  return (
32	    <motion.div
33	      className={className}
34	      initial="hidden"
35	      animate="visible"
36	      variants={{ hidden: {}, visible: { transition: { staggerChildren: stagger } } }}
37	    >
38	      {Children.map(children, (child) =>
39	        child ? (
40	          <motion.div
41	            variants={{
42	              hidden: { opacity: 0, x: dir.x * distance, y: dir.y * distance },
43	              visible: { opacity: 1, x: 0, y: 0, transition: { duration, ease: "easeOut" } },
44	            }}
45	          >
46	            {child}
47	          </motion.div>
48	        ) : null
49	      )}
50	    </motion.div>
51	  );
52	};
53	
54	export { StaggerList };
