59	
60	function slugify(name: string): string {
61	  const raw = name
62	    .toLowerCase()
63	    .replace(/[^a-z0-9]+/g, "-")
64	    .replace(/^-|-$/g, "")
65	    .slice(0, 60);
66	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
67	  // Pad short slugs with a numeric suffix so they always pass the constraint.
68	  if (raw.length < 3) return raw.padEnd(3, "1");
69	  return raw;
70	}
71	
72	// DB constraint only accepts 6-digit hex (#rrggbb).
73	// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
74	function isValidHex(value: string): boolean {
75	  return /^#[0-9A-Fa-f]{6}$/.test(value);
76	}
